    "shortDescription": "सांस्कृतिक स्थलों, पहाड़ी इलाकों के नज़ारों, वन्यजीवों और दक्षिणी समुद्र तटों को मिलाते हुए सत्रह दिन और सोलह रातें।",
    "overview": "हबाराना, सिगिरिया, हिरीवाद्ना और मिनेरिया की खोज करें, साथ ही एक हॉट एयर बलून अनुभव और अनुराधापुर की यात्रा करें। दंबुल्ला गुफा मंदिर, कंडी के दांत का मंदिर, एक सांस्कृतिक कार्यक्रम, अंबुलुवावा टॉवर और शाही वनस्पति उद्यान की खोज करें। नुवारा एलिया होते हुए रम्बोडा झरना, ग्रेगरी झील और एक स्ट्रॉबेरी फार्म देखें, फिर एला में नाइन आर्च ब्रिज, मिनी आदम पीक और रावणा फॉल्स देखें। दक्षिणी भाग में याला नेशनल पार्क, मिरीसा, गले डच किला, कोसगोडा सी टर्टल हैचरी और बेंटोटा सनसेट क्रूज़ शामिल हैं। अंत में कोलंबो शहर का भ्रमण, खरीदारी और स्ट्रीट फूड का आनंद लें।",
